body { font: 16px/1.5 system-ui, sans-serif; color: #1f2a1f; background: #fbfaf5; margin: 0; }
main { max-width: 440px; margin: 32px auto; padding: 0 16px; }
.step { color: #6b6b6b; font-size: 14px; }
label { display: block; font-weight: 600; margin-top: 16px; }
input { font: inherit; width: 100%; min-height: 44px; padding: 8px; border: 1px solid #8a8a8a; border-radius: 6px; }
.hint { color: #a3a3a3; font-size: 13px; margin: 4px 0 0; }
button { font: inherit; min-height: 44px; margin-top: 24px; padding: 8px 20px; background: #2f6b3a; color: #fff; border: 0; border-radius: 6px; }
.toast { position: fixed; bottom: 16px; left: 16px; right: 16px; padding: 10px 14px; background: #1f2a1f; color: #fff; border-radius: 6px; }

